+const MODES = new Set(['uppercase', 'lowercase', 'slug']);
+const ALLOWED_ARGS = new Set(['text', 'mode', 'trim']);
+
+function slugify(text) {
+  return text
+    .toLowerCase()
+    .trim()
+    .replace(/[^a-z0-9]+/g, '-')
+    .replace(/^-+|-+$/g, '');
+}
+
+export async function listTools() {
+  return [
+    {
+      name: 'text_transform',
+      description: 'Transform text using the specified mode: uppercase, lowercase, or slug.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          text: { type: 'string', description: 'The text to transform.' },
+          mode: {
+            type: 'string',
+            enum: ['uppercase', 'lowercase', 'slug'],
+            description: 'The transformation mode.'
+          },
+          trim: {
+            type: 'boolean',
+            default: true,
+            description: 'Whether to trim the text before transforming (default true).'
+          }
+        },
+        required: ['text', 'mode'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'text_transform') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_ARGS.has(key)) {
+      throw new Error(`Unexpected argument: ${key}`);
+    }
+  }
+
+  const { text, mode, trim = true } = args;
+
+  if (typeof text !== 'string') {
+    throw new Error('text is required and must be a string');
+  }
+  if (typeof mode !== 'string' || !MODES.has(mode)) {
+    throw new Error('mode is required and must be one of: uppercase, lowercase, slug');
+  }
+  if (trim !== undefined && typeof trim !== 'boolean') {
+    throw new Error('trim must be a boolean');
+  }
+
+  let result = text;
+  if (trim) {
+    result = result.trim();
+  }
+
+  if (mode === 'uppercase') {
+    result = result.toUpperCase();
+  } else if (mode === 'lowercase') {
+    result = result.toLowerCase();
+  } else if (mode === 'slug') {
+    result = slugify(result);
+  }
+
+  return { content: [{ type: 'text', text: result }] };
+}
